import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cross_entropy_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 1024
#define MAX_LOGITS 10  // num_classes from input

__global__ void fused_cross_entropy_kernel(const float* logits, 
                                         const long* targets,
                                         float* loss,
                                         int batch_size,
                                         int num_classes) {
    extern __shared__ float shared_mem[];

    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    if (batch_idx >= batch_size) return;

    const float* class_logits = logits + batch_idx * num_classes;
    long target = targets[batch_idx];

    // Step 1: Find max logit for numerical stability
    float max_logit = -INFINITY;
    for (int i = tid; i < num_classes; i += blockDim.x) {
        max_logit = fmaxf(max_logit, class_logits[i]);
    }
    shared_mem[tid] = max_logit;
    __syncthreads();

    // Reduction for max logit
    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_mem[tid] = fmaxf(shared_mem[tid], shared_mem[tid + s]);
        }
        __syncthreads();
    }
    float max_val = shared_mem[0];
    __syncthreads();

    // Step 2: Compute exp(logits - max_logit) and sum
    float exp_sum = 0.0f;
    for (int i = tid; i < num_classes; i += blockDim.x) {
        exp_sum += expf(class_logits[i] - max_val);
    }
    shared_mem[tid] = exp_sum;
    __syncthreads();

    // Reduction for sum
    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_mem[tid] += shared_mem[tid + s];
        }
        __syncthreads();
    }
    float log_sum = logf(shared_mem[0]) + max_val;
    __syncthreads();

    // Step 3: Compute loss for target class
    if (tid == 0) {
        float log_softmax = class_logits[target] - log_sum;
        atomicAdd(loss, -log_softmax);
    }
}

torch::Tensor fused_cross_entropy_cuda(torch::Tensor logits, torch::Tensor targets) {
    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(torch::kCUDA);
    auto loss = torch::zeros(1, options);

    int batch_size = logits.size(0);
    int num_classes = logits.size(1);

    dim3 block_dim(BLOCK_SIZE);
    dim3 grid_dim(batch_size);

    size_t shared_mem_size = BLOCK_SIZE * sizeof(float);

    fused_cross_entropy_kernel<<<grid_dim, block_dim, shared_mem_size>>>(
        logits.data_ptr<float>(),
        targets.data_ptr<long>(),
        loss.data_ptr<float>(),
        batch_size,
        num_classes
    );

    return loss / batch_size;
}
"""

cross_entropy_cpp = "torch::Tensor fused_cross_entropy_cuda(torch::Tensor logits, torch::Tensor targets);"

cross_entropy_ext = load_inline(
    name="cross_entropy",
    cpp_sources=cross_entropy_cpp,
    cuda_sources=cross_entropy_source,
    functions=["fused_cross_entropy_cuda"],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.cross_entropy_fn = cross_entropy_ext.fused_cross_entropy_cuda

    def forward(self, predictions, targets):
        return self.cross_entropy_fn(predictions, targets)
